    /// <summary>
    /// §3.3 <c>campground.device.v1</c>: a stable key for one physical device.
    /// <para>
    /// <b>A grouping key, never an access boundary.</b> Every input is client-supplied, and both the provider's
    /// merged records and <see cref="DeviceClient.FallbackKey"/> can put two real devices under one key. Use it
    /// to group, name and remember things per device; never to let something through (an allow-list keyed on it
    /// would widen whenever two devices collapse). Bonfire's device restrictions match the raw DeviceId, and an
    /// empty list there means "any device".
    /// </para>
    /// <para>
    /// What Bonfire found about DeviceIds (read from the clients' source, 2026-08 and 2026-09):
    /// <list type="bullet">
    /// <item>jellyfin-web mints one id per <i>origin</i> and keeps it in localStorage (<c>_deviceId2</c>):
    /// <c>btoa(userAgent + "|" + Date.now())</c>. It does not rotate. One computer still holds several: the LAN
    /// address and the public URL are two origins, as are a second browser profile or cleared site data. Ids from
    /// one browser share their first 40-odd characters (the base64 of the user agent), so never shorten an id from
    /// the front to tell two apart.</item>
    /// <item>Jellyfin Android TV sends the raw <c>ANDROID_ID</c> (16 hex) when nobody is signed in, and
    /// <c>sha1(ANDROID_ID + "+" + userId)</c> (40 hex) once someone is. Jellyfin for Android appends the user id
    /// with no separator. So one television has a different id per account, and another at its sign-in screen.</item>
    /// <item>Jellyfin's own <c>Device</c> rows belong to sessions: <c>SessionManager.Logout</c> deletes them, and so
    /// does the Session Cleaner plugin. Don't rely on them surviving; keep your own record.</item>
    /// </list>
    /// </para>
    /// </summary>
    internal sealed record DeviceIdentity(string StableKey, string? DisplayName, bool FromProvider);

    /// <summary>Arguments of <c>getDevice</c>.</summary>
    internal sealed record DeviceQuery(string? DeviceId, string? AppName, string? DeviceName, Guid? UserId);

    /// <summary>Calls <c>campground.device.v1</c> (provided by Bonfire) with a shared fallback.</summary>
    internal static class DeviceClient
    {
        internal const string GetDeviceOp = "getDevice";

        /// <summary>The device's identity; the fallback key when Bonfire is missing.</summary>
        internal static async Task<DeviceIdentity> GetAsync(DeviceQuery query, CancellationToken ct = default)
        {
            var result = await Capabilities.TryInvokeAsync<DeviceIdentity>(
                CapabilityNames.Device, GetDeviceOp, query, ct: ct).ConfigureAwait(false);
            if (result is { StableKey.Length: > 0 })
            {
                return result with { FromProvider = true };
            }

            return new DeviceIdentity(FallbackKey(query.AppName, query.DeviceName, query.UserId), query.DeviceName, false);
        }

        /// <summary>
        /// App + device model + user, hashed. Survives the device ID changing (a reinstalled app, a second origin,
        /// cleared site data, or a client that derives its id from the user); two identical TVs used by the same
        /// account collapse into one, which is the accepted cost, and the reason this key is never an access
        /// boundary (see <see cref="DeviceIdentity"/>).
        /// </summary>
        internal static string FallbackKey(string? appName, string? deviceName, Guid? userId)
        {
            var raw = string.Join(
                "|",
                (appName ?? string.Empty).Trim().ToLowerInvariant(),
                (deviceName ?? string.Empty).Trim().ToLowerInvariant(),
                (userId ?? Guid.Empty).ToString("N"));
            var hash = SHA256.HashData(Encoding.UTF8.GetBytes(raw));
            return "fb:" + Convert.ToHexString(hash, 0, 12).ToLowerInvariant();
        }

        /// <summary>For the provider (Bonfire).</summary>
        internal static void Provide(string pluginId, int minor, Func<DeviceQuery, CancellationToken, Task<DeviceIdentity?>> getDevice)
            => Capabilities.Provide(
                CapabilityNames.Device,
                pluginId,
                minor,
                new CapabilityHost().On(GetDeviceOp, getDevice).Build());
    }
